const n={gongyong:{zijinmima:"Mật khẩu giao dịch"},yonghu:{zijinmimashezhi:"Thiết lập mật khẩu giao dịch",tiaoguozijinmimajixuzhuce:"Bỏ qua thiết lập mật khẩu giao dịch để tiếp tục đăng ký",xiugaizijinmima:"Thay đổi mật khẩu giao dịch"},yingshe:{miaoheyue:"Giao dịch quyền chọn",miaoheyuejiaoyi:"Giao dịch quyền chọn",dazongshangpin:"Giao dịch hợp đồng tương lai",dazongjiaoyidingdan:"Lệnh giao dịch hợp đồng tương lai",dazongzhanghu:"Tài khoản giao dịch hợp đồng tương lai",dazongzichan:"Tài sản giao dịch hợp đồng tương lai",dazongyue:"Số dư giao dịch hợp đồng tương lai",dazongshangpinjiaoyi:"Giao dịch hợp đồng tương lai"},cbot455:{guizeshouce:"Sổ tay quy tắc",jianguanzhiyan:"Hướng dẫn quản lý",guanyuwomen:"Về chúng tôi",tiyanhuihuang:"TRẢI NGHIỆM SỰ RỰC RỠ CỦA",huangjinqihuo:"Hợp đồng tương lai vàng",quantianhoujiayi:"Giao dịch suốt ngày đêm trên những thị trường không bao giờ ngủ",fengxianjiyubingcun:"NƠI RỦI RO GẶP GỠ CƠ HỘI.",zhaodaochanpin:"Tìm sản phẩm hợp đồng tương lai vàng phù hợp với bạn",tansuochanpin:"Khám phá các sản phẩm vàng của chúng tôi để tìm lựa chọn lý tưởng trong những thị trường phái sinh vàng sôi động nhất thế giới, được cá nhân và tổ chức toàn cầu sử dụng và giao dịch 23 giờ mỗi ngày.",zuigao24h:"Cao nhất 24h",zuidi24h:"Thấp nhất 24h",chengjiaoliang24h:"Khối lượng 24h",tianjiazixuan:"+ DANH SÁCH THEO DÕI",yichuzixuan:"- DANH SÁCH THEO DÕI",lijijiaoyi:"GIAO DỊCH NGAY",jiesuojihui:"Mở khóa thế giới cơ hội",jiarudingjianjiaoyizhe:"Gia nhập hàng ngũ các nhà giao dịch hàng đầu đã khám phá sức mạnh của hợp đồng tương lai và quyền chọn. Khi tạo tài khoản giao dịch CBOT, bạn sẽ được truy cập miễn phí vào các tài nguyên đào tạo cao cấp, phân tích thị trường và các công cụ tiên tiến.",kaishijiayi:"BẮT ĐẦU GIAO DỊCH",chuangjianzhanghu:"TẠO TÀI KHOẢN",shijiahuangjin:"Trải nghiệm thử giao dịch hợp đồng tương lai vàng",shijiahuangjinmiaoshu:"Nâng cao kỹ năng giao dịch vàng và khám phá cơ hội mới với dữ liệu thị trường thực trong Trình mô phỏng giao dịch không rủi ro của chúng tôi.",kaishilianxi:"BẮT ĐẦU LUYỆN TẬP",texingyoushi:"Tính năng và lợi ích",lingxianliudongxing:"Thanh khoản hàng đầu",lingxianliudongxingmiaoshu:"Với hơn 200.000 hợp đồng được giao dịch trung bình mỗi ngày và OI đạt đỉnh vượt 900.000, bạn có thể vào/ra vị thế một cách dễ dàng.",linghuozhixing:"Thực thi giao dịch linh hoạt",linghuozhixingmiaoshu:"Truy cập thanh khoản qua sổ lệnh giới hạn trung tâm, giao dịch khối hoặc RFQ.",anquanbaozhang:"An toàn và bảo mật",anquanbaozhangmiaoshu:"Giảm thiểu rủi ro tín dụng đối tác trong thị trường được thanh toán bù trừ tập trung và chịu sự quản lý của CFTC.",geyefangwen:"Truy cập điện tử qua đêm",geyefangwenmiaoshu:"Quản lý vị thế trong giờ làm việc EMEA và APAC khi tin tức và sự kiện toàn cầu có tác động đến thị trường diễn ra.",qihuoganggan:"Đòn bẩy hợp đồng tương lai",qihuogangganmiaoshu:"Kiểm soát giá trị danh nghĩa lớn hơn với số vốn tương đối nhỏ, gia tăng sức mua của bạn.",jiarutiaozhang:"Biến tò mò thành tự tin</br>Biến bất định thành hành động</br>Bắt đầu con đường làm giàu của bạn",lijizhuce:"ĐĂNG KÝ NGAY",wuyulunbijiaoyiliang:"Khối lượng giao dịch hàng ngày vượt trội mang lại thanh khoản dẫn đầu ngành",zhaodaoliudongxing:"Tìm thanh khoản để thực hiện chiến lược giao dịch bạn mong muốn—khi bạn muốn—với mức giá hiệu quả nhất. Các sản phẩm chuẩn toàn cầu trong mọi loại tài sản chính giúp bạn hành động nhanh để nắm bắt cơ hội hoặc giảm thiểu rủi ro trên các thị trường bạn giao dịch.",lianxiwomen:"Liên hệ với chúng tôi",yazhouzongbu:"Trụ sở châu Á",cmejituan:"Tập đoàn CBOT",dianhua:"Điện thoại",youxiang:"Email",richengjiaoliang:"Khối lượng giao dịch hàng ngày và lãi suất mở",zuihougengxin:"Cập nhật lần cuối",suoyoushuju:"Tất cả số liệu tính bằng triệu.",jiaoyiriqi:"NGÀY GIAO DỊCH",zongji:"TỔNG",cmeglobex:"CBOT GLOBEX",cmeclearport:"CBOT CLEARPORT",gongkaihanjia:"GIAO DỊCH HÔ HÀO",chicang:"LÃI SUẤT MỞ",richengjiao:"Khối lượng giao dịch hàng ngày",chicangliang:"Lãi suất mở",mran_biaoti:"Thông báo tư vấn quản lý thị trường hiện hành (MRAN)",mran_jianjie:"Kể từ khi CME Group được thành lập thông qua việc sáp nhập CME và CBOT năm 2007, sau đó sáp nhập với NYMEX/COMEX năm 2008, Bộ phận Quản lý Thị trường đã ban hành một loạt Thông báo Tư vấn Quản lý Thị trường (MRAN) nhằm cung cấp hướng dẫn về quy tắc cho thị trường. Các MRAN hiện hành được liệt kê bên dưới và được nhóm theo sàn giao dịch áp dụng.",mran_lianxi:"Nếu có câu hỏi liên quan đến bất kỳ MRAN nào được liệt kê dưới đây, vui lòng liên hệ Bộ phận Quản lý Thị trường qua email tại {email}.",mran_huoqv:"Để lấy bản sao các MRAN đã phát hành trước đây hoặc các thông báo tư vấn khác của CME Group, vui lòng sử dụng Tìm kiếm Thông báo Tư vấn.",cme_intro:"Là thị trường phái sinh hàng đầu thế giới, CME Group là nơi thế giới đến để quản lý rủi ro. Chúng tôi cho phép khách hàng giao dịch hợp đồng tương lai, quyền chọn, thị trường tiền mặt và OTC, tối ưu hóa danh mục và phân tích dữ liệu – trao quyền cho các bên tham gia thị trường trên toàn cầu quản lý rủi ro hiệu quả và nắm bắt cơ hội. Các sàn giao dịch của CME Group cung cấp danh mục sản phẩm chuẩn toàn cầu rộng nhất trên tất cả các loại tài sản chính như lãi suất, chỉ số cổ phiếu, ngoại hối, năng lượng, nông sản và kim loại. Chúng tôi đối mặt với sự bất định và biến động bằng sự tự tin và minh bạch, trong suốt vòng đời giao dịch và trên toàn thế giới.",cme_motto:"Hành động, giao dịch, tăng trưởng, đầu tư.",cme_description:"Giữa những lực lượng toàn cầu không ngừng biến động, CME Group cung cấp các sản phẩm và bộ dữ liệu đổi mới trên mọi loại tài sản chính trên toàn cầu, giúp cá nhân và tổ chức nâng tầm chiến lược giao dịch. Tìm hiểu thêm trong video này.",exchange_rules_title:"Quy tắc riêng theo sàn cho CME, CBOT, NYMEX và COMEX",exchange_rules_description:"CME, CBOT, NYMEX và COMEX là các Sàn giao dịch độc lập, mỗi sàn vẫn là Thị trường Hợp đồng được Chỉ định đã đăng ký với CFTC với trách nhiệm tự quản lý và duy trì bộ quy tắc riêng. Để cung cấp khuôn khổ quản lý chung cho người dùng thị trường, các sổ quy tắc đã được hài hòa đáng kể, giúp các quy tắc song song về cấu trúc, đánh số và ngôn ngữ khi có thể.",cme_footer_desc:"Chicago Board of Trade (CBOT)<br><br>Thành lập và lịch sử: Được thành lập năm 1848 bởi 82 thương nhân ngũ cốc nhằm quản lý giao dịch ngũ cốc. Năm 1865, CBOT giới thiệu các hợp đồng tương lai tiêu chuẩn hóa và hệ thống ký quỹ, đặt nền móng cho giao dịch hợp đồng tương lai hiện đại.<br><br>Sản phẩm giao dịch chính: Với lịch sử lâu đời, đây là một trong những sàn giao dịch nông sản tiêu biểu nhất thế giới, chủ yếu giao dịch hợp đồng tương lai ngô, đậu tương và lúa mì.<br><br>Chuyển đổi số: CBOT đã chuyển đổi hoàn toàn từ giao dịch hô hào truyền thống sang giao dịch điện tử, đóng cửa hầu hết các hoạt động giao dịch sàn vào năm 2015.",server724:"Dịch vụ chăm sóc khách hàng trực tiếp 24/7",quanqiuzongbu:"Trụ sở toàn cầu",zhijiage:"Chicago",rengongfuwutishi:"Để tiết kiệm thời gian quý báu của bạn và đảm bảo an toàn cho nguồn vốn, chúng tôi cung cấp dịch vụ hỗ trợ trực tiếp chuyên biệt 7*24.",nongchanpin:"Nông sản",nengyuan:"Năng lượng",jinshu:"Kim loại",nongchanpinshuoming:"Phòng ngừa rủi ro giá trong thị trường Nông sản toàn cầu đang mở rộng với các sản phẩm chuẩn – hợp đồng tương lai và quyền chọn Lúa mì, Ngô và Đậu tương. Tìm kiếm cơ hội mới để thực hiện các giao dịch theo sự kiện với độ chính xác cao bằng các hợp đồng Nông sản có tính thanh khoản và được giao dịch sôi động.",nengyuanshuoming:"Nhận giá chính xác, theo thời gian thực cho các thị trường năng lượng được quan tâm nhiều nhất. Giao dịch các sản phẩm chuẩn – Dầu thô WTI, Khí tự nhiên Henry Hub, Dầu Brent, Xăng RBOB – được sử dụng trên toàn cầu để thiết lập đường cong giá cho quản lý rủi ro và khám phá cơ hội năng lượng.",jinshushuoming:"Thể hiện quan điểm về đường cong kỳ hạn kim loại. Giao dịch chênh lệch kim loại liên thị trường hoặc khám phá đa dạng sản phẩm từ chuẩn kích thước đầy đủ đến hợp đồng kích thước nhỏ hơn, giúp bạn tăng độ chính xác cho danh mục kim loại của mình."},zichan:{jiamihuobichongzhi:"Nạp tiền bằng tiền điện tử",jiamihuobitixian:"Rút tiền bằng tiền điện tử",yinhangkachongzhi:"Nạp tiền",yinhangkatixian:"Rút tiền"}};export{n as default};
